"""AI attribution: this whole file was generated by Claude (Anthropic) in Claude Code, following
design decisions made by the author. See ATTRIBUTION.md for details.

Mirror vs ear damage (2026-11-24; design written down in docs/iterations.md before computing; descriptive, not
registered). Reads the reliability confirmation's stored outputs (dev, replication); fits nothing, changes no verdict.

Per noise type x level (clean, +10 ... +40 dB) x side (respond: R-hear questions; stop: S-move questions), question-level
accuracy as in the registered claims (p1v4_reliability_confirm.build_items, subset "all"):
  x = ear damage   main system without labels (D_off_none): accuracy at the type's clean level minus at the level
  y = mirror       main system minus old head, both with true labels (T_off_truth)   (= the M1 statistic per cell)
  u = label help   main system with true labels minus without labels (T_off_truth minus D_off_none)
By construction y = (clean gap) - x + u, so the slope of y on x and u carry the information, not the correlation.
The noise type of a unit is its background-noise recording's folder (p1v4_score.unit_table "noise").
usage: [P1V4_FINAL_RUN=1] .venv-gpu/Scripts/python.exe -X utf8 scripts/p1v4_mirror_vs_ears.py compute dev|replication
       .venv/Scripts/python.exe -X utf8 scripts/p1v4_mirror_vs_ears.py figure | figure-newnoise   (matplotlib venv)
"""
import json
import os
import sys
import time

import numpy as np

sys.path.insert(0, os.path.dirname(os.path.abspath(__file__)))

RES = "results/main_v04"
FIG = f"{RES}/figures"
SIDES = {"r_hear": "Respond", "s_move": "Stop"}
NOISY = ("dnoise10", "dnoise20", "dnoise30", "dnoise40")
DB = {"dclean": 0, "dnoise10": 10, "dnoise20": 20, "dnoise30": 30, "dnoise40": 40}
# the reference categorical palette (dataviz skill references/palette.md, light mode), fixed order, never cycled
PALETTE = ["#2a78d6", "#eb6834", "#1baf7a", "#eda100", "#e87ba4", "#008300", "#6250d6"]
ORDER = ("OOFFICE", "DLIVING", "STRAFFIC", "DKITCHEN", "PRESTO", "NFIELD", "NRIVER")       # dev first, then replication
NAMES = {"OOFFICE": "office", "DLIVING": "living room", "STRAFFIC": "street traffic", "DKITCHEN": "kitchen",
         "PRESTO": "restaurant", "NFIELD": "field", "NRIVER": "river"}


def env_name(path):
    p = str(path).replace("\\", "/")
    return p.split("/")[-2] if "/" in p else p


def compute(split):
    import p1v4_reliability_confirm as CF
    import p1v4_score as S
    t0 = time.time()
    if split != "dev":
        CF.check_freeze()
    rows, rows_by, groups, wins = CF.grid(split)
    T = S.unit_table(rows, {}, S.load_groups(split))
    Q, _, _, _ = CF.build_items(split)
    print(f"items built ({time.time() - t0:.0f} s)", flush=True)
    env_of = {u: env_name(T[u]["noise"]) for u in T}
    cells = {}
    for p in SIDES:
        for lv in DB:
            for cond in ("D_off_none", "T_off_truth"):
                for sysname in ("2d", "old head"):
                    items = Q[(p, cond, sysname, lv, "all")]
                    by = {}
                    for x in items:
                        by.setdefault(env_of[x[0]], []).append((x[0], bool(x[6])))
                    for env, xs in by.items():
                        c = cells.setdefault(f"{p}|{env}|{lv}", {"side": p, "env": env, "level": lv, "db": DB[lv]})
                        c[f"{sysname}|{cond}"] = float(np.mean([r for _, r in xs]))
                        c["n_questions"] = len(xs)
                        c["n_units"] = len({u for u, _ in xs})
    for c in cells.values():
        clean = cells[f"{c['side']}|{c['env']}|dclean"]
        c["ear_damage"] = clean["2d|D_off_none"] - c["2d|D_off_none"]
        c["mirror"] = c["2d|T_off_truth"] - c["old head|T_off_truth"]
        c["label_help"] = c["2d|T_off_truth"] - c["2d|D_off_none"]
    out = {"split": split, "design": "experiment_log.md 2026-11-24 11:40", "cells": cells,
           "seconds": round(time.time() - t0)}
    json.dump(out, open(f"{RES}/mirror_vs_ears_{split}.json", "w"), indent=1)
    for p in SIDES:
        print(SIDES[p])
        for env in sorted({c["env"] for c in cells.values()}):
            row = [cells[f"{p}|{env}|{lv}"] for lv in DB]
            print(f"  {env:9s} " + "  ".join(f"{c['db']:2d} dB: dmg {100 * c['ear_damage']:+5.1f} mir "
                                                f"{100 * c['mirror']:+5.1f} help {100 * c['label_help']:+5.1f}"
                                                for c in row), flush=True)


def summary(cells):
    """Least-squares slope of y on x over the noisy cells, per side, and the label help at the largest damages."""
    out = {}
    for p in SIDES:
        cs = [c for c in cells if c["side"] == p and c["level"] in NOISY]
        x = np.array([c["ear_damage"] for c in cs])
        y = np.array([c["mirror"] for c in cs])
        u = np.array([c["label_help"] for c in cs])
        slope, icpt = np.polyfit(x, y, 1)
        big = x >= np.quantile(x, 0.75)
        out[p] = {"n_cells": len(cs), "slope": float(slope), "intercept": float(icpt),
                  "corr": float(np.corrcoef(x, y)[0, 1]), "slope_label_help_on_damage": float(np.polyfit(x, u, 1)[0]),
                  "label_help_mean": float(u.mean()), "label_help_top_quarter_damage": float(u[big].mean()),
                  "damage_max": float(x.max()), "cells_damage_under_5": int((x < 0.05).sum()),
                  "mirror_in_cells_damage_under_5": [float(v) for v in y[x < 0.05]]}
    return out


def figure():
    import matplotlib
    matplotlib.use("Agg")
    import matplotlib.pyplot as plt
    cells = []
    for split in ("dev", "replication"):
        d = json.load(open(f"{RES}/mirror_vs_ears_{split}.json"))
        for c in d["cells"].values():
            cells.append(dict(c, split=split))
    summ = summary(cells)
    json.dump({"summary": summ, "cells": cells}, open(f"{RES}/mirror_vs_ears.json", "w"), indent=1)
    ink, ink2, grid = "#1f1f1e", "#5f5e5a", "#e4e3df"
    plt.rcParams.update({"font.family": "DejaVu Sans", "font.size": 9, "axes.edgecolor": ink2, "axes.labelcolor": ink,
                         "xtick.color": ink2, "ytick.color": ink2, "text.color": ink})
    fig, axes = plt.subplots(1, 2, figsize=(7.2, 3.4), sharex=True, sharey=True)
    for ax, p in zip(axes, SIDES):
        ax.grid(True, color=grid, linewidth=0.6)
        ax.set_axisbelow(True)
        ax.axhline(0, color=ink2, linewidth=0.8)
        for i, env in enumerate(ORDER):
            cs = sorted([c for c in cells if c["side"] == p and c["env"] == env], key=lambda c: c["db"])
            if not cs:
                continue
            xs = [100 * c["ear_damage"] for c in cs]
            ys = [100 * c["mirror"] for c in cs]
            mk = "o" if cs[0]["split"] == "dev" else "s"
            ax.plot(xs, ys, color=PALETTE[i], linewidth=1.2, zorder=2)
            ax.scatter(xs, ys, s=[14 + 0.9 * c["db"] for c in cs], marker=mk, color=PALETTE[i], edgecolor="white",
                       linewidth=0.8, zorder=3, label=f"{NAMES[env]} ({'dev' if cs[0]['split'] == 'dev' else 'repl.'})")
        s = summ[p]
        xx = np.array([0, 100 * s["damage_max"]])
        ax.plot(xx, s["intercept"] * 100 + s["slope"] * xx, color=ink2, linewidth=1.0, linestyle="--", zorder=1)
        ax.set_title(f"{SIDES[p]}: slope {s['slope']:+.2f} over {s['n_cells']} noisy cells", fontsize=9, color=ink)
        ax.set_xlabel("Ear damage: accuracy lost without labels (points)")
    axes[0].set_ylabel("Mirror: main system minus old head,\ntrue labels (points)")
    h, lab = axes[1].get_legend_handles_labels()
    lg = fig.legend(h, lab, loc="lower center", ncol=4, frameon=False, fontsize=8, bbox_to_anchor=(0.5, -0.02),
                    title="Noise type (marker grows with the added noise: clean, +10, +20, +30, +40 dB; "
                          "dashed: least-squares line)", title_fontsize=8)
    lg.get_title().set_color(ink2)
    fig.tight_layout(rect=(0, 0.13, 1, 1))
    os.makedirs(FIG, exist_ok=True)
    for ext in ("png", "pdf"):
        fig.savefig(f"{FIG}/mirror_vs_ears.{ext}", dpi=200, bbox_inches="tight")
    print(json.dumps(summ, indent=1))


def figure_newnoise():
    """The new-corpus check (plan summarised in docs/iterations.md): the 16 noisy cells per side of the four MS-SNSD types,
    over the 28 DEMAND cells (grey) and their least-squares line."""
    import matplotlib
    matplotlib.use("Agg")
    import matplotlib.pyplot as plt
    old = json.load(open(f"{RES}/mirror_vs_ears.json"))
    new = json.load(open(f"{RES}/newnoise_replication.json"))["mirror_cells"]
    cells_new = list(new.values())
    summ_new = summary(cells_new)
    order = ("AirConditioner", "VacuumCleaner", "WasherDryer", "CopyMachine")
    names = {"AirConditioner": "air conditioner", "VacuumCleaner": "vacuum cleaner", "WasherDryer": "washer/dryer",
             "CopyMachine": "copy machine"}
    ink, ink2, grid, grey = "#1f1f1e", "#5f5e5a", "#e4e3df", "#b9b8b2"
    plt.rcParams.update({"font.family": "DejaVu Sans", "font.size": 9, "axes.edgecolor": ink2, "axes.labelcolor": ink,
                         "xtick.color": ink2, "ytick.color": ink2, "text.color": ink})
    fig, axes = plt.subplots(1, 2, figsize=(7.2, 3.4), sharex=True, sharey=True)
    for ax, p in zip(axes, SIDES):
        ax.grid(True, color=grid, linewidth=0.6)
        ax.set_axisbelow(True)
        ax.axhline(0, color=ink2, linewidth=0.8)
        oc = [c for c in old["cells"] if c["side"] == p and c["level"] in NOISY]
        ax.scatter([100 * c["ear_damage"] for c in oc], [100 * c["mirror"] for c in oc], s=16, color=grey,
                   edgecolor="none", zorder=1, label="DEMAND, 7 types (dev + replication)")
        so = old["summary"][p]
        xx = np.array([0, 100 * max(so["damage_max"], max(c["ear_damage"] for c in cells_new if c["side"] == p))])
        ax.plot(xx, 100 * so["intercept"] + so["slope"] * xx, color=ink2, linewidth=1.0, linestyle="--", zorder=1)
        for i, t in enumerate(order):
            cs = sorted([c for c in cells_new if c["side"] == p and c["env"] == t], key=lambda c: c["db"])
            xs = [100 * c["ear_damage"] for c in cs]
            ys = [100 * c["mirror"] for c in cs]
            ax.plot(xs, ys, color=PALETTE[i], linewidth=1.2, zorder=2)
            ax.scatter(xs, ys, s=[14 + 0.9 * c["db"] for c in cs], marker="D", color=PALETTE[i], edgecolor="white",
                       linewidth=0.8, zorder=3, label=f"{names[t]} (MS-SNSD)")
        sn = summ_new[p]
        ax.set_title(f"{SIDES[p]}: new types slope {sn['slope']:+.2f} (DEMAND {so['slope']:+.2f})", fontsize=9)
        ax.set_xlabel("Ear damage: accuracy lost without labels (points)")
    axes[0].set_ylabel("Mirror: main system minus old head,\ntrue labels (points)")
    h, lab = axes[1].get_legend_handles_labels()
    lg = fig.legend(h, lab, loc="lower center", ncol=3, frameon=False, fontsize=8, bbox_to_anchor=(0.5, -0.02),
                    title="Replication units with another corpus's noise (marker grows with the added noise: own SNR, "
                          "+10 ... +40 dB); dashed: the DEMAND line", title_fontsize=8)
    lg.get_title().set_color(ink2)
    fig.tight_layout(rect=(0, 0.13, 1, 1))
    for ext in ("png", "pdf"):
        fig.savefig(f"{FIG}/mirror_vs_ears_newnoise.{ext}", dpi=200, bbox_inches="tight")
    json.dump({"summary_new_types": summ_new, "summary_demand": old["summary"]},
              open(f"{RES}/mirror_vs_ears_newnoise.json", "w"), indent=1)
    print(json.dumps(summ_new, indent=1))


if __name__ == "__main__":
    if len(sys.argv) >= 2 and sys.argv[1] == "compute" and len(sys.argv) == 3:
        compute(sys.argv[2])
    elif len(sys.argv) == 2 and sys.argv[1] == "figure":
        figure()
    elif len(sys.argv) == 2 and sys.argv[1] == "figure-newnoise":
        figure_newnoise()
    else:
        raise SystemExit(__doc__)
